import argparse,hashlib,json,sys
from pathlib import Path
import numpy as np,pandas as pd
def main():
    sys.stdout.reconfigure(encoding='utf-8');p=argparse.ArgumentParser();p.add_argument('--project-root',type=Path,required=True);p.add_argument('--revision-root',type=Path,required=True);a=p.parse_args();out=a.revision_root/'10_R2.9'
    for x in ['data','results','response','manuscript']:(out/x).mkdir(exist_ok=True,parents=True)
    base=a.project_root/'benchmark_core/data/unified_matrix_v5';inventory=pd.read_csv(base/'source_inventory_v5.csv');inventory.to_csv(out/'data/source_inventory_readonly_copy.csv',index=False)
    f=base/'observation_matrix_v5.csv';counts=[];missing=[];scales=[]
    labels=['measured_total_efficiency','measured_position_rate','measured_outcome_frequency'];cols=['source_family','source_dataset','label_type','measurement_scale','replicate_count','total_read_count','qc_level']+labels
    for d in pd.read_csv(f,usecols=cols,chunksize=100000,low_memory=False):
        counts.append(d.groupby(['source_family','source_dataset','label_type','measurement_scale'],dropna=False).size().rename('rows').reset_index())
        for source,g in d.groupby('source_family'):
            for label in labels:
                v=pd.to_numeric(g[label],errors='coerce');scales.append(dict(source_family=source,field=label,finite=int(v.notna().sum()),outside_0_1=int(((v<0)|(v>1)).sum())))
            missing.append(dict(source_family=source,rows=len(g),read_count_available=int(g.total_read_count.notna().sum()),replicate_count_available=int(g.replicate_count.notna().sum())))
    groups=['source_family','source_dataset','label_type','measurement_scale'];c=pd.concat(counts).groupby(groups,dropna=False).rows.sum().reset_index();c.to_csv(out/'results/catalog_source_measurement_inventory.csv',index=False)
    pd.DataFrame(scales).groupby(['source_family','field'])[['finite','outside_0_1']].sum().reset_index().to_csv(out/'results/numerical_scale_audit.csv',index=False);pd.DataFrame(missing).groupby('source_family').sum().reset_index().to_csv(out/'results/catalog_metadata_availability.csv',index=False)
    contracts=[
        dict(analysis='Original scalar/classification and matched-condition analyses',source='BE-Hive',event='Processed broad any-edit fraction; input A at 3–10 does not redefine label',denominator='Author-retained assay reads',replicates='Arithmetic mean of available replicate fractions; design/context aggregation as specified',handling='Same observed readout for every model; within-source editor/cell strata and matched contrasts',evidence='Original T1 and T4 frozen scoring inputs; R2.1 endpoint report; original Fig6 source tables'),
        dict(analysis='Original product/position panels',source='BE-Hive bystander',event='Conditional products/rates among available edited products',denominator='Source conditional edited-product mass; not total-editing read denominator',replicates='Author merged outcome profile',handling='Original model-specific panels retained; execution corrected; paired common inputs added',evidence='R2.1 corrected T3 inputs; R2.2 common-key tables'),
        dict(analysis='Added random common-window profiles',source='BE-Hive 12kChar; mES and HEK293T',event='Canonical A>G at guide 3–10, conditional on >=1 window event',denominator='Sum of complete available source-product frequencies containing a canonical window event',replicates='Source merged products; all products of selected targets retained',handling='Fixed input-only samples; identical projection/conditioning; source association retained',evidence='R2.3 input-only pool, freeze, full-product audit and seven-model predictions'),
        dict(analysis='Added source-transfer challenge',source='Marquart ABEmax integrated library; HEK293T',event='At least one canonical A>G event at guide 3–10',denominator='Author-retained reads including WT and outside-window products',replicates='Source processed frequencies; upstream author comparison-subset selection retained',handling='Separate endpoint analysis; frozen backends; known CRISPRon exclusions; no pooling with BE-Hive',evidence='R2.1 endpoint identities, 127-target panel and full source-product labels'),
        dict(analysis='Retrospective recommendation',source='37 BE-Hive groups and 2 CRISPRon groups',event='Source-reported activity; within-group rankings and top-10% labels',denominator='Source-specific activity readout; candidate-group instances for recommendation metrics',replicates='Median repeated measurement per design within group',handling='Candidate ranking within source/editor/context group; equal-group summaries; source stratification',evidence='R2.7 original metric replication and R2.8 source/guide sensitivities')]
    pd.DataFrame(contracts).to_csv(out/'results/analysis_endpoint_contracts.csv',index=False)
    report=dict(status='PASS',converted_matrix_rows=int(c.rows.sum()),converted_matrix_families=sorted(c.source_family.unique()),resource_catalog_family_count=int(inventory.source_family.nunique()),catalog_is_not_a_single_pooled_performance_dataset=True,raw_reads_reprocessed=False,source_filters_preserved=True,source_specific_original_primary_panels_retained=True,numerical_scaling_does_not_equal_endpoint_harmonization=True,endpoint_identity_audit='CRISPRon canonical-window training labels verified in R2.1; other unresolved native training-event details remain qualified.',clinical_or_causal_adjustment=False,protocol_scope='Unavailable upstream QC/protocol fields are retained as unknown; no invented batch adjustment or interchangeable-event claim.',source_sha256=hashlib.sha256(f.read_bytes()).hexdigest())
    (out/'results/validation.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report,ensure_ascii=False))
if __name__=='__main__':main()
